if (to_write == 0) to_write = 1;
bool ok = static_cast<ots::OTSStream*>(stream)->WriteRaw(data.data(), to_write);
// Property: ExpandingMemoryStream::WriteRaw should succeed iff write does not exceed limit
// at current position (taking into account it can grow up to limit).
bool expect_ok = (to_write <= remaining);
FUZZ_ASSERT(ok == expect_ok, "WriteRaw result must reflect whether write fits within limit");
// Validation: We exercised both success and failure; stream remains valid and is returned.

