bool ok = static_cast<ots::OTSStream*>(stream)->Write(payload.data(), n);
FUZZ_SET_ATTR_INT(stream, "last_write_n", static_cast<int>(n));
FUZZ_SET_ATTR_INT(stream, "last_write_ok", ok ? 1 : 0);
// Validation: zero-length requests should return false; other results depend on stream capacity.

// Seek within the currently allocated range. For ExpandingMemoryStream, positions
// up to current allocated length are valid; Tell() is always within that, so [0, Tell()] is safe.
off_t cur = stream->Tell();
if (cur < 0) { FUZZ_BAIL(); }
size_t span = static_cast<size_t>(cur);
size_t back = span ? (*FUZZ_PARAM(unsigned int) % (span + 1)) : 0;
off_t target = static_cast<off_t>(span - back);
bool ok = static_cast<ots::OTSStream*>(stream)->Seek(target);
FUZZ_ASSERT(ok, "Seek to [0, Tell()] must succeed");
// Validation: We constrained target to a valid range; stream remains usable.

off_t pos = static_cast<const ots::OTSStream*>(stream)->Tell();
FUZZ_SET_ATTR_INT(stream, "last_tell", static_cast<int>(pos));
// Validation: Tell has no side effects; we record the position for downstream use.

// Write a small number of zero bytes as padding.
