bool ok = static_cast<ots::OTSStream*>(stream)->Pad(bytes);
FUZZ_SET_ATTR_INT(stream, "last_pad", static_cast<int>(bytes));
FUZZ_SET_ATTR_INT(stream, "last_pad_ok", ok ? 1 : 0);
