static_cast<ots::OTSStream*>(stream)->WriteU8(v);
// Validation: No special constraints; boolean result depends on stream space.

uint16_t v = static_cast<uint16_t>(*FUZZ_PARAM(unsigned int));
static_cast<ots::OTSStream*>(stream)->WriteU16(v);
// Validation: Host-endian converted to big-endian internally; we just invoke it.

