import random
from typing import List

# Data type: arbitrary binary data
# Target usage summary:
# - FUZZ_PARAM_STR() supplies a std::string payload used as raw bytes for Write/WriteRaw.
# - Stubs cap writes around 1..512 bytes typically, sometimes 0 length for Write().
# - Streams under test: MemoryStream and ExpandingMemoryStream; they do not
#   interpret content, but checksum and alignment paths in OTSStream::Write
#   can be exercised by varying lengths and content patterns to cross 4-byte
#   boundaries.
#
# Strategy for generating interesting, yet valid buffers:
# - Produce arbitrary binary payloads that include a mix of patterns:
#   * All-zero runs (to exercise Pad-like effects and easy checksum values)
#   * 0xFF runs (opposite extreme)
#   * Incrementing/decrementing sequences (exercise memcpy paths and 4-byte batches)
#   * Random bytes
#   * Repeated 32-bit words to tick checksum accumulation on boundaries
# - Vary total length in the typical range [1, 512], sometimes longer but <= 4096.
# - Ensure non-empty by default since many stubs force to_write >= 1, but we
#   also include zero-length edge case regions inside the buffer for callers
#   that might use subsequences.
# - Keep it pure bytes; no external I/O.

MAX_TOTAL = 4096

def _chunk(pattern: str, n: int, seed: int) -> bytes:
    rnd = random.Random(seed)
    if pattern == "zeros":
        return bytes([0]) * n
    if pattern == "ffs":
        return bytes([0xFF]) * n
    if pattern == "inc":
        return bytes([(i % 256) for i in range(n)])
    if pattern == "dec":
        return bytes([((255 - i) % 256) for i in range(n)])
    if pattern == "rand":
        return bytes([rnd.randrange(256) for _ in range(n)])
    if pattern == "wordrep":
        # Repeat a 4-byte word; choose from a small interesting set.
        words = [0x00000000, 0xFFFFFFFF, 0x01020304, 0xA5A5A5A5, 0x11223344, 0x89ABCDEF]
        w = words[rnd.randrange(len(words))]
        b = w.to_bytes(4, byteorder="big")
        return (b * (n // 4)) + b[: n % 4]
    if pattern == "alt01":
        return bytes([0x00 if (i & 1) == 0 else 0x01 for i in range(n)])
    if pattern == "alt7f80":
        return bytes([0x7F if (i & 1) == 0 else 0x80 for i in range(n)])
    return bytes([0] * n)

def _build_sections(seed: int, total_len: int) -> List[bytes]:
    rnd = random.Random(seed)
    # Choose 3..8 sections of varying patterns
    num_sections = rnd.randrange(3, 9)
    remaining = total_len
    sections: List[bytes] = []
    patterns = ["zeros", "ffs", "inc", "dec", "rand", "wordrep", "alt01", "alt7f80"]

    for i in range(num_sections):
        if i == num_sections - 1:
            n = remaining
        else:
            # Bias sizes to create a mix of small and medium chunks
            base = max(1, remaining // (num_sections - i))
            low = max(1, base // 2)
            high = max(1, int(base * 1.5))
            n = rnd.randrange(low, min(high, remaining) + 1)
        pat = rnd.choice(patterns)
        sections.append(_chunk(pat, n, seed + i * 101))
        remaining -= n
        if remaining <= 0:
            break
    # Occasionally align a section boundary to 4 bytes by inserting small padding,
    # to exercise both aligned and unaligned states in OTSStream::Write.
    if sections and rnd.random() < 0.5:
        pad = rnd.randrange(0, 4)
        if pad:
            pad_bytes = _chunk("zeros", pad, seed + 999)
            if sum(len(s) for s in sections) + pad <= total_len:
                sections.append(pad_bytes)
            else:
                # Adjust last section if needed
                last = sections.pop()
                if len(last) > pad:
                    sections.append(last[:-pad])
                    sections.append(pad_bytes)
                else:
                    sections.append(last)
    return sections

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Choose total length with a strong bias toward <= 512, but sometimes larger up to 4096.
    if rnd.random() < 0.8:
        total_len = rnd.randrange(1, 513)
    else:
        total_len = rnd.randrange(513, MAX_TOTAL + 1)

    sections = _build_sections(seed, total_len)
    buf = b"".join(sections)

    # Ensure the final size is exactly total_len (trim or pad zeros if necessary).
    if len(buf) > total_len:
        buf = buf[:total_len]
    elif len(buf) < total_len:
        buf += bytes([0]) * (total_len - len(buf))

    # Occasionally prepend or append short headers/footers to create different
    # starting alignments and checksum behaviors without imposing structure.
    tweak = rnd.randrange(0, 3)
    if tweak == 1 and len(buf) + 3 <= MAX_TOTAL:
        # Prepend 3 bytes to force misalignment
        buf = b"HDR" + buf
    elif tweak == 2 and len(buf) + 4 <= MAX_TOTAL:
        # Append 4 bytes to finish on 4-byte boundary
        buf = buf + b"TAIL"

    # Cap to MAX_TOTAL strictly
    return buf[:MAX_TOTAL]
